// Verify the API's HMAC signature (same scheme as /internal), then plan the job.
const crypto = require('crypto');
const req = $input.first().json;
const h = req.headers || {};
const ts = h['x-klyro-timestamp'];
const sig = h['x-klyro-signature'];
const body = req.body || {};
const raw = JSON.stringify(body);
const secret = $env.KLYRO_HMAC_SECRET;
const expected = crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
const fresh = Math.abs(Date.now() - Number(ts)) < 5 * 60 * 1000;
if (!ts || !sig || !fresh || sig.length !== expected.length ||
    !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
  throw new Error('Rejected scrape-start: bad or expired signature');
}
if (!body.scrapeJobId || !body.workspaceId) throw new Error('scrape-start missing ids');
const queries = (body.queries || []).filter(Boolean);
return [{ json: {
  workspaceId: body.workspaceId,
  scrapeJobId: body.scrapeJobId,
  queries,
  country: body.country || 'US',
  maxResults: Math.min(Number(body.maxResults) || 200, 1000),
  filters: body.filters || {},
  // Rough budget: ~60s per query, 2–30 minutes total.
  maxTimeSec: Math.min(1800, Math.max(120, 60 * queries.length)),
} }];

const p = $('Verify & plan').first().json;
return [{ json: { method: 'POST', path: '/internal/scrape/progress',
  body: { workspaceId: p.workspaceId, scrapeJobId: p.scrapeJobId,
          status: p.queries.length ? 'running' : 'failed',
          ...(p.queries.length ? {} : { error: 'Target has no categories/keywords to search' }) } } }];

// Poll gosom until the job finishes (or we give up after ~40 minutes).
const s = $input.first().json.Status;
const finished = s === 'ok' || s === 'failed';
const timedOut = !finished && $runIndex >= 80;
return [{ json: { done: finished || timedOut, status: timedOut ? 'timeout' : s } }];

// Parse the scraper CSV, apply the target filters, dedupe, chunk for the API.
const p = $('Verify & plan').first().json;
const status = $('Done?').last().json.status;
if (status !== 'ok') {
  return [{ json: { skip: true, found: 0, failed: true,
    error: status === 'timeout' ? 'Scraper timed out' : 'Scraper job failed' } }];
}
const text = String($input.first().json.data || '');

function parseCsv(t) {
  const rows = []; let row = []; let f = ''; let q = false;
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (q) {
      if (c === '"') { if (t[i + 1] === '"') { f += '"'; i++; } else q = false; }
      else f += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(f); f = ''; }
    else if (c === '\n') { row.push(f); rows.push(row); row = []; f = ''; }
    else if (c !== '\r') f += c;
  }
  if (f.length || row.length) { row.push(f); rows.push(row); }
  return rows;
}
const rows = parseCsv(text);
const head = rows.shift() || [];
const col = (r, k) => r[head.indexOf(k)] ?? '';
const num = (v) => { const n = Number(String(v).replace(/,/g, '')); return Number.isFinite(n) ? n : null; };
const json = (v) => { try { return JSON.parse(v); } catch { return null; } };

const F = p.filters || {};
const seen = new Set();
const titleCount = {};
const places = rows.filter((r) => r.length > 3).map((r) => {
  const addr = json(col(r, 'complete_address')) || {};
  return {
    name: col(r, 'title').trim(),
    website: col(r, 'website').trim() || null,
    phone: col(r, 'phone').trim() || null,
    address: col(r, 'address').trim() || null,
    city: addr.city || null,
    country: p.country,
    category: col(r, 'category').trim() || null,
    rating: num(col(r, 'review_rating')),
    reviewCount: num(col(r, 'review_count')),
    lat: num(col(r, 'latitude')),
    lng: num(col(r, 'longitude')),
    placeId: col(r, 'place_id').trim() || null,
  };
}).filter((x) => x.name);
for (const x of places) titleCount[x.name.toLowerCase()] = (titleCount[x.name.toLowerCase()] || 0) + 1;

const records = places.filter((x) => {
  const key = x.placeId || `${x.name}|${x.address}`;
  if (seen.has(key)) return false; seen.add(key);
  if (F.hasWebsite === true && !x.website) return false;
  if (F.hasWebsite === false && x.website) return false;
  if (F.minRating != null && (x.rating ?? 0) < F.minRating) return false;
  if (F.maxRating != null && x.rating != null && x.rating > F.maxRating) return false;
  if (F.minReviews != null && (x.reviewCount ?? 0) < F.minReviews) return false;
  // Same business name 3+ times in one job ≈ a chain.
  if (F.excludeChains !== false && titleCount[x.name.toLowerCase()] >= 3) return false;
  return true;
}).slice(0, p.maxResults);

if (!records.length) return [{ json: { skip: true, found: places.length } }];
const out = [];
for (let i = 0; i < records.length; i += 50) {
  out.push({ json: {
    found: places.length,
    method: 'POST', path: '/internal/leads/batch',
    idempotencyKey: `${p.scrapeJobId}-batch-${i / 50}`,
    body: { workspaceId: p.workspaceId, source: 'maps', reference: p.scrapeJobId,
            records: records.slice(i, i + 50) },
  } });
}
return out;

// Final progress report for the admin UI.
const p = $('Verify & plan').first().json;
const parsed = $('Parse & chunk').all().map((i) => i.json);
const first = parsed[0] || {};
let ingested = 0;
for (const it of $input.all()) ingested += Number(it.json?.data?.created ?? 0);
const failed = Boolean(first.failed);
return [{ json: { method: 'POST', path: '/internal/scrape/progress',
  idempotencyKey: `${p.scrapeJobId}-done`,
  body: { workspaceId: p.workspaceId, scrapeJobId: p.scrapeJobId,
          status: failed ? 'failed' : 'enriched',
          found: Number(first.found || 0), ingested,
          ...(failed ? { error: first.error } : {}) } } }];
